import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';
const $=s=>document.querySelector(s), scene=new THREE.Scene();
scene.background=new THREE.Color(0x788987);scene.fog=new THREE.FogExp2(0x788987,.0028);
const camera=new THREE.PerspectiveCamera(54,innerWidth/innerHeight,.1,900);
const renderer=new THREE.WebGLRenderer({antialias:true,alpha:false});renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.05;$('#game').appendChild(renderer.domElement);
scene.add(new THREE.HemisphereLight(0xc9d8d2,0x35402f,2.1));const sun=new THREE.DirectionalLight(0xffdfb3,3.2);sun.position.set(-65,95,55);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);sun.shadow.camera.left=-110;sun.shadow.camera.right=110;sun.shadow.camera.top=110;sun.shadow.camera.bottom=-110;scene.add(sun);
const mat=(color,rough=.85,metal=0)=>new THREE.MeshStandardMaterial({color,roughness:rough,metalness:metal});
const groundMat=mat(0x74794b), roadMat=mat(0x373d3d), lineMat=mat(0xe4ddbb), houseMat=mat(0xc8b89a), roofMat=mat(0x514b45), treeMat=mat(0x384c36), trunkMat=mat(0x594b36), carPaint=mat(0xb9c4bd,.42,.3), glassMat=new THREE.MeshStandardMaterial({color:0x263e43,roughness:.22,metalness:.3});
const ground=new THREE.Mesh(new THREE.PlaneGeometry(900,900),groundMat);ground.rotation.x=-Math.PI/2;ground.position.y=-.12;ground.receiveShadow=true;scene.add(ground);
const roads=new THREE.Group();scene.add(roads);
function road(x,z,w,d,rotation=0){const m=new THREE.Mesh(new THREE.PlaneGeometry(w,d),roadMat);m.rotation.x=-Math.PI/2;m.rotation.z=rotation;m.position.set(x,.005,z);m.receiveShadow=true;roads.add(m);if(d>w){for(let z0=-d/2+3;z0<d/2;z0+=9){const l=new THREE.Mesh(new THREE.PlaneGeometry(.14,4),lineMat);l.rotation.x=-Math.PI/2;l.position.set(x,.018,z+z0);roads.add(l)}}else{for(let x0=-w/2+3;x0<w/2;x0+=9){const l=new THREE.Mesh(new THREE.PlaneGeometry(4,.14),lineMat);l.rotation.x=-Math.PI/2;l.position.set(x+x0,.018,z);roads.add(l)}}}
road(0,0,10,900);road(-90,0,6,900);road(75,0,6,900);for(let z=-330;z<400;z+=78)road(0,z,180,7);
// Long agricultural field furrows create scale and direction.
const furrows=new THREE.Group();scene.add(furrows);for(let s of [-1,1])for(let x=14;x<245;x+=5){const f=new THREE.Mesh(new THREE.PlaneGeometry(.15,850),new THREE.MeshBasicMaterial({color:x%10<5?0x9b9257:0x666d42,transparent:true,opacity:.23}));f.rotation.x=-Math.PI/2;f.position.set(s*x,.002,0);furrows.add(f)}
function box(parent,x,y,z,w,h,d,material,cast=true){const o=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),material);o.position.set(x,y,z);o.castShadow=cast;o.receiveShadow=true;parent.add(o);return o}
function makeHouse(x,z,scale=1){const g=new THREE.Group();g.position.set(x,0,z);box(g,0,1.2,0,7*scale,2.4*scale,6*scale,houseMat);const roof=new THREE.Mesh(new THREE.ConeGeometry(5.5*scale,2.2*scale,4),roofMat);roof.position.y=3.1*scale;roof.rotation.y=Math.PI/4;roof.castShadow=true;g.add(roof);box(g,1,0.65,3.02,.9*scale,1.3*scale,.12,mat(0x514333));for(let side of [-1,1])box(g,side*2,1.35,3.04,1.05*scale,.8*scale,.08,glassMat,false);scene.add(g);return g}
function makeBarn(x,z){const g=new THREE.Group();g.position.set(x,0,z);box(g,0,2,0,10,4,13,mat(0x873f32));const r=new THREE.Mesh(new THREE.ConeGeometry(8,3,4),roofMat);r.rotation.y=Math.PI/4;r.position.y=5;g.add(r);box(g,0,1,6.58,4,2,.1,mat(0x63332a));scene.add(g)}
function makeTree(x,z,scale=1){const g=new THREE.Group();g.position.set(x,0,z);const tr=new THREE.Mesh(new THREE.CylinderGeometry(.13*scale,.25*scale,2.2*scale,6),trunkMat);tr.position.y=1.1*scale;tr.castShadow=true;g.add(tr);const crown=new THREE.Mesh(new THREE.ConeGeometry(1.05*scale,3.3*scale,7),treeMat);crown.position.y=3.1*scale;crown.castShadow=true;g.add(crown);scene.add(g);return g}
// Town blocks and roadside farm compounds.
const buildings=[];for(let row=0;row<3;row++)for(let col=0;col<5;col++){let x=-50+col*23,z=135+row*19;if(Math.abs(x)<12)continue;buildings.push(makeHouse(x,z,.72+Math.random()*.25))}makeBarn(-66,215);makeBarn(57,232);
for(let i=0;i<100;i++){let x=(Math.random()<.5?-1:1)*(18+Math.random()*190),z=-380+Math.random()*760;if(Math.abs(z%78)<8&&Math.abs(x)<88)continue;if(Math.abs(x)<14||Math.abs(x-75)<9||Math.abs(x+90)<9)continue;makeTree(x,z,.65+Math.random()*.8)}
// grain silos beside the farm road
for(const [x,z] of [[-53,205],[-43,206],[62,245]]){let silo=new THREE.Mesh(new THREE.CylinderGeometry(3,3,13,16),mat(0x9caaa8,.46,.38));silo.position.set(x,6.5,z);silo.castShadow=true;scene.add(silo);const cap=new THREE.Mesh(new THREE.ConeGeometry(3,1.5,16),mat(0x697978,.42,.35));cap.position.set(x,13.8,z);scene.add(cap)}
// Wind turbines on the far prairie.
const turbines=[];for(let i=0;i<8;i++){const x=(i%2?1:-1)*(110+Math.random()*90),z=-170+i*55;const tower=new THREE.Mesh(new THREE.CylinderGeometry(.35,.8,24,8),mat(0xc9cfca,.55,.3));tower.position.set(x,12,z);scene.add(tower);const hub=new THREE.Group();hub.position.set(x,24,z);scene.add(hub);for(let j=0;j<3;j++){const blade=new THREE.Mesh(new THREE.BoxGeometry(.48,10,.22),mat(0xdce1dc,.45,.25));blade.position.y=5;blade.rotation.z=-.16;hub.add(blade);blade.rotation.z=j*Math.PI*2/3}turbines.push(hub)}

