turbines.push(hub)}
// Supercell anvils, rolling cloud layers and rain curtains.
const cloudMat=new THREE.MeshStandardMaterial({color:0x475354,roughness:1,transparent:true,opacity:.88});const clouds=new THREE.Group();scene.add(clouds);for(let i=0;i<34;i++){const puff=new THREE.Mesh(new THREE.SphereGeometry(1,12,9),cloudMat);const x=-130+Math.random()*260,z=-170+Math.random()*150;puff.position.set(x,39+Math.random()*19,z);puff.scale.set(12+Math.random()*22,5+Math.random()*9,12+Math.random()*20);clouds.add(puff)}
const anvil=new THREE.Mesh(new THREE.SphereGeometry(1,24,16),new THREE.MeshStandardMaterial({color:0x3e4a4b,roughness:1,transparent:true,opacity:.88}));anvil.position.set(38,51,-72);anvil.scale.set(68,18,47);scene.add(anvil);
const rainGeo=new THREE.BufferGeometry(),rainCount=850,rainPositions=new Float32Array(rainCount*3);for(let i=0;i<rainCount;i++){rainPositions[i*3]=(Math.random()-.5)*140;rainPositions[i*3+1]=Math.random()*60;rainPositions[i*3+2]=(Math.random()-.5)*160}rainGeo.setAttribute('position',new THREE.BufferAttribute(rainPositions,3));const rain=new THREE.Points(rainGeo,new THREE.PointsMaterial({color:0xc2d6d4,size:.12,transparent:true,opacity:.46}));rain.position.set(0,0,-55);scene.add(rain);
const tornado=new THREE.Group();scene.add(tornado);tornado.position.set(39,0,-65);
function createFunnel(){const verts=[],indices=[],segments=36,rings=30;for(let j=0;j<=rings;j++){const v=j/rings,y=v*29,r=(.65+v*5.7)*(0.91+.1*Math.sin(v*18));for(let i=0;i<=segments;i++){const a=i/segments*Math.PI*2;verts.push(Math.cos(a)*r,y,Math.sin(a)*r)}}for(let j=0;j<rings;j++)for(let i=0;i<segments;i++){let a=j*(segments+1)+i,b=a+segments+1;indices.push(a,b,a+1,b,b+1,a+1)}const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(verts,3));g.setIndex(indices);g.computeVertexNormals();return g}
const funnel=new THREE.Mesh(createFunnel(),new THREE.MeshStandardMaterial({color:0x555d5b,roughness:1,transparent:true,opacity:.8,side:THREE.DoubleSide}));funnel.position.y=0;tornado.add(funnel);
const funnel2=new THREE.Mesh(new THREE.CylinderGeometry(.4,4.2,17,18,1,true),new THREE.MeshStandardMaterial({color:0x929996,transparent:true,opacity:.18,side:THREE.DoubleSide,depthWrite:false}));funnel2.position.y=19;tornado.add(funnel2);
const debris=new THREE.Group();tornado.add(debris);for(let i=0;i<46;i++){const bit=new THREE.Mesh(new THREE.BoxGeometry(.14+Math.random()*.25,.12+Math.random()*.35,.12+Math.random()*.25),i%4?mat(0x756b55):mat(0x9a8b70));bit.userData={r:3+Math.random()*10,a:Math.random()*Math.PI*2,y:1+Math.random()*24,s:.7+Math.random()*2};debris.add(bit)}
const vortexRings=[];for(let j=0;j<3;j++){const ring=new THREE.Mesh(new THREE.TorusGeometry(2.2+j*1.6,.035,5,50),new THREE.MeshBasicMaterial({color:0xbfc4b9,transparent:true,opacity:.3}));ring.position.y=3+j*3;ring.rotation.x=Math.PI/2;ring.userData={y:3+j*3,s:1+j*.35};tornado.add(ring);vortexRings.push(ring)}
// Player fleet, simplified but individually readable chase vehicles.
const fleet=[{name:'RANGER 4×4',type:'Storm intercept',cost:0,color:0xb9c4bd,speed:1,armor:1},{name:'PRAIRIE PICKUP',type:'Radar embarqué',cost:1200,color:0xb77b4a,speed:1.04,armor:.78},{name:'FIELD VAN',type:'Station scientifique',cost:2600,color:0xd9d3bb,speed:.83,armor:.9},{name:'APEX TIV',type:'Intercepteur blindé',cost:5200,color:0x677675,speed:.72,armor:1.8},{name:'DOPPLER TRUCK',type:'Radar mobile',cost:7600,color:0xb7b9ac,speed:.65,armor:1.25},{name:'PRAIRIE RUNNER',type:'Haute mobilité',cost:3900,color:0x75844d,speed:1.27,armor:.7}];let owned=new Set([0]),selected=0,car=new THREE.Group();scene.add(car);
function buildCar(i){scene.remove(car);car=new THREE.Group();scene.add(car);const spec=fleet[i],body=mat(spec.color,.35,.32),dark=mat(0x263035,.45,.2);box(car,0,.8,0,2.2,.72,4.3,body);box(car,0,1.43,-.25,1.85,.78,2.15,body);box(car,0,1.48,-.25,1.62,.58,1.88,glassMat,false);box(car,0,.75,-2.16,2.12,.24,.22,dark);box(car,0,.72,2.17,2.12,.25,.22,dark);for(let x of [-1.12,1.12])for(let z of [-1.35,1.35]){const wheel=new THREE.Mesh(new THREE.CylinderGeometry(.48,.48,.28,16),dark);wheel.rotation.z=Math.PI/2;wheel.position.set(x,.49,z);wheel.castShadow=true;car.add(wheel)}for(let x of [-.72,.72]){const light=new THREE.Mesh(new THREE.BoxGeometry(.34,.18,.08),mat(0xffe6aa,.35));light.position.set(x,.96,2.19);car.add(light)}if(i===2){for(let x of [-.5,.5]){const mast=new THREE.Mesh(new THREE.CylinderGeometry(.035,.035,1.3,6),mat(0x6a7774,.4,.5));mast.position.set(x,2.45,-.5);car.add(mast)}}if(i===4){const dish=new THREE.Mesh(new THREE.CylinderGeometry(.8,.8,.18,18),mat(0xadb8b4,.4,.55));dish.position.set(0,2.15,-.25);car.add(dish)}car.position.set(0,0,4);car.castShadow=true;car.userData={speed:0,heading:0,health:100,fuel:87};$('#vehicleName').textContent=spec.name;$('#fuel').textContent=Math.round(car.userData.fuel)+'%'}buildCar(0);

